  quality_score, language_level, active, version, source_batch, approved_by
) VALUES ('meb2_restaurant_01', 'restaurant: Make the promise easy to repeat', 'simple-summary', 'simple_summary', '{"title":"restaurant: Make the promise easy to repeat","what_it_means":"restaurant customers need explain the one clear promise before they feel ready to choose {{businessName}} in {{location}}. For this food business, show food, freshness, timing, menu clarity, price clarity, and how people can order, reserve, or visit.","what_to_do":["Write one line that says who it helps, what they get, and what to do next using dish photos, clean kitchen clips, price clarity, and review screenshots.","Make this about make the promise easy to repeat for signature dishes and meals, not a general brand update.","End with this exact next step: WhatsApp to reserve or order."],"example":"{{businessName}} can use this in {{location}} by showing dish photos and saying: \"Here is the simple way to get signature dishes and meals. WhatsApp to reserve or order.\"","why_this_helps":"This works for a restaurant because people decide faster when they can see proof, understand the offer, and know the next step without asking five extra questions.","how_to_check":"Ask three people what they think you sell after reading it. Also check replies, saves, useful questions, and people who mention this restaurant post."}', '["restaurant","food_beverage"]', '["pre_launch"]', '["families","office_workers","students"]', '["instagram","whatsapp","google_business"]', '["standard_product"]', '["local_store","delivery","pickup"]', '["build_trust","explain_product"]', '["no_budget","low_budget","medium_budget"]', '["local_city","india","kerala"]', '["unclear_offer","generic_message"]', 'medium', 'important', 'today', 5, 'beginner', 1, 'review-002-market-expansion', 'review-002-market-expansion', 'local-review');
