) VALUES ('meb2_restaurant_12', 'restaurant: Use the first week to build belief', 'seven-day-plan', 'seven_day_plan', '{"title":"restaurant: Use the first week to build belief","what_it_means":"restaurant customers need create a simple first-week rhythm before they feel ready to choose {{businessName}} in {{location}}. For this food business, show food, freshness, timing, menu clarity, price clarity, and how people can order, reserve, or visit.","what_to_do":["Day 1: show the problem people have before choosing signature dishes and meals.","Day 2: show dish photos. Day 3: answer a price or timing doubt. Day 4: show process. Day 5: show proof. Day 6: make the offer. Day 7: repeat the next step: WhatsApp to reserve or order.","Keep every post simple enough for a busy person to understand in ten seconds."],"example":"{{businessName}} can use this in {{location}} by showing dish photos and saying: \"Here is the simple way to get signature dishes and meals. WhatsApp to reserve or order.\"","why_this_helps":"This works for a restaurant because people decide faster when they can see proof, understand the offer, and know the next step without asking five extra questions.","how_to_check":"Review which day got the most useful replies. Also check replies, saves, useful questions, and people who mention this restaurant post."}', '["restaurant","food_beverage"]', '["pre_launch","early_stage"]', '["families","office_workers","students"]', '["instagram","whatsapp","google_business"]', '["standard_product"]', '["local_store","delivery","pickup"]', '["launch_awareness","first_30_customers"]', '["no_budget","low_budget","medium_budget"]', '["local_city","india","kerala"]', '["inconsistent_content","no_plan"]', 'easy', 'urgent', 'this_week', 5, 'beginner', 1, 'review-002-market-expansion', 'review-002-market-expansion', 'local-review');
