  quality_score, language_level, active, version, source_batch, approved_by
) VALUES ('meb2_healthcare_clinic_11', 'healthcare clinic: Follow up without sounding needy', 'whatsapp-message', 'whatsapp_message', '{"title":"healthcare clinic: Follow up without sounding needy","what_it_means":"healthcare clinic customers need move a chat forward before they feel ready to choose {{businessName}} in {{location}}. For this clinic, keep the language about appointments, comfort, timing, doctor clarity, and care; avoid ordering or delivery language.","what_to_do":["Send a reply that names consultations and health services, gives one useful detail, and asks only one question.","Make this about follow up without sounding needy for consultations and health services, not a general brand update.","End with this exact next step: call or WhatsApp for appointment timing."],"example":"{{businessName}} can reply: \"Yes, we can help with consultations and health services. Send me the main detail and I will guide the next step clearly.\"","why_this_helps":"This works for a healthcare clinic because people decide faster when they can see proof, understand the offer, and know the next step without asking five extra questions.","how_to_check":"Count how many chats move to booking, order, signup, or demo. Also check replies, saves, useful questions, and people who mention this healthcare clinic post.","copy_ready_text":"Hi, thanks for asking about {{businessName}}. For consultations and health services, the easiest next step is this: call or WhatsApp for appointment timing. I can also send proof, price range, and timing so you can decide without confusion."}', '["healthcare","clinic"]', '["pre_launch"]', '["families","working_adults","parents"]', '["instagram","whatsapp","google_business","website"]', '["appointment_service"]', '["appointment","clinic"]', '["more_enquiries","more_bookings","more_orders","more_signups"]', '["no_budget","low_budget","medium_budget"]', '["local_city","india","kerala"]', '["slow_replies","lost_chats"]', 'easy', 'urgent', 'today', 5, 'beginner', 1, 'review-002-market-expansion', 'review-002-market-expansion', 'local-review');
