) VALUES ('meb2_healthcare_clinic_12', 'healthcare clinic: Use the first week to build belief', 'seven-day-plan', 'seven_day_plan', '{"title":"healthcare clinic: Use the first week to build belief","what_it_means":"healthcare clinic customers need create a simple first-week rhythm before they feel ready to choose {{businessName}} in {{location}}. For this clinic, keep the language about appointments, comfort, timing, doctor clarity, and care; avoid ordering or delivery language.","what_to_do":["Day 1: show the problem people have before choosing consultations and health services.","Day 2: show doctor profile. Day 3: answer a price or timing doubt. Day 4: show process. Day 5: show proof. Day 6: make the offer. Day 7: repeat the next step: call or WhatsApp for appointment timing.","Keep every post simple enough for a busy person to understand in ten seconds."],"example":"{{businessName}} can use this in {{location}} by showing doctor profile and saying: \"Here is the simple way to get consultations and health services. call or WhatsApp for appointment timing.\"","why_this_helps":"This works for a healthcare clinic because people decide faster when they can see proof, understand the offer, and know the next step without asking five extra questions.","how_to_check":"Review which day got the most useful replies. Also check replies, saves, useful questions, and people who mention this healthcare clinic post."}', '["healthcare","clinic"]', '["pre_launch","early_stage"]', '["families","working_adults","parents"]', '["instagram","whatsapp","google_business","website"]', '["appointment_service"]', '["appointment","clinic"]', '["launch_awareness","first_30_customers"]', '["no_budget","low_budget","medium_budget"]', '["local_city","india","kerala"]', '["inconsistent_content","no_plan"]', 'easy', 'urgent', 'this_week', 5, 'beginner', 1, 'review-002-market-expansion', 'review-002-market-expansion', 'local-review');
