  location_tags, problem_tags, difficulty, priority, timeframe,
  quality_score, language_level, active, version, source_batch, approved_by
) VALUES ('meb2_boutique_11', 'boutique: Follow up without sounding needy', 'whatsapp-message', 'whatsapp_message', '{"title":"boutique: Follow up without sounding needy","what_it_means":"boutique customers need move a chat forward before they feel ready to choose {{businessName}} in {{location}}. For this boutique, show real proof, timing, price clarity, and the next step people should take.","what_to_do":["Send a reply that names clothes, outfits, and styling help, gives one useful detail, and asks only one question.","Make this about follow up without sounding needy for clothes, outfits, and styling help, not a general brand update.","End with this exact next step: send size and occasion on WhatsApp."],"example":"{{businessName}} can reply: \"Yes, we can help with clothes, outfits, and styling help. Send me the main detail and I will guide the next step clearly.\"","why_this_helps":"This works for a boutique because people decide faster when they can see proof, understand the offer, and know the next step without asking five extra questions.","how_to_check":"Count how many chats move to booking, order, signup, or demo. Also check replies, saves, useful questions, and people who mention this boutique post.","copy_ready_text":"Hi, thanks for asking about {{businessName}}. For clothes, outfits, and styling help, the easiest next step is this: send size and occasion on WhatsApp. I can also send proof, price range, and timing so you can decide without confusion."}', '["boutique","fashion","retail"]', '["pre_launch"]', '["women","students","young_professionals"]', '["instagram","whatsapp","google_business"]', '["standard_product"]', '["local_store","retail","custom_order"]', '["more_enquiries","more_bookings","more_orders","more_signups"]', '["no_budget","low_budget","medium_budget"]', '["local_city","india","kerala"]', '["slow_replies","lost_chats"]', 'easy', 'urgent', 'today', 5, 'beginner', 1, 'review-002-market-expansion', 'review-002-market-expansion', 'local-review');
