  quality_score, language_level, active, version, source_batch, approved_by
) VALUES ('meb2_boutique_12', 'boutique: Use the first week to build belief', 'seven-day-plan', 'seven_day_plan', '{"title":"boutique: Use the first week to build belief","what_it_means":"boutique customers need create a simple first-week rhythm before they feel ready to choose {{businessName}} in {{location}}. For this boutique, show real proof, timing, price clarity, and the next step people should take.","what_to_do":["Day 1: show the problem people have before choosing clothes, outfits, and styling help.","Day 2: show real model photos. Day 3: answer a price or timing doubt. Day 4: show process. Day 5: show proof. Day 6: make the offer. Day 7: repeat the next step: send size and occasion on WhatsApp.","Keep every post simple enough for a busy person to understand in ten seconds."],"example":"{{businessName}} can use this in {{location}} by showing real model photos and saying: \"Here is the simple way to get clothes, outfits, and styling help. send size and occasion on WhatsApp.\"","why_this_helps":"This works for a boutique because people decide faster when they can see proof, understand the offer, and know the next step without asking five extra questions.","how_to_check":"Review which day got the most useful replies. Also check replies, saves, useful questions, and people who mention this boutique post."}', '["boutique","fashion","retail"]', '["pre_launch","early_stage"]', '["women","students","young_professionals"]', '["instagram","whatsapp","google_business"]', '["standard_product"]', '["local_store","retail","custom_order"]', '["launch_awareness","first_30_customers"]', '["no_budget","low_budget","medium_budget"]', '["local_city","india","kerala"]', '["inconsistent_content","no_plan"]', 'easy', 'urgent', 'this_week', 5, 'beginner', 1, 'review-002-market-expansion', 'review-002-market-expansion', 'local-review');
