  quality_score, language_level, active, version, source_batch, approved_by
) VALUES ('meb2_boutique_18', 'boutique: Track the signal that matters', 'measurement', 'measurement', '{"title":"boutique: Track the signal that matters","what_it_means":"boutique customers need know what is working before they feel ready to choose {{businessName}} in {{location}}. For this boutique, show real proof, timing, price clarity, and the next step people should take.","what_to_do":["Track one weekly signal for this boutique: useful replies, bookings, orders, signups, calls, or website clicks depending on the business model.","Write the number before posting, after posting, and at the end of the week.","Keep the action if the number improves; change the post angle if it attracts wrong questions."],"example":"{{businessName}} can use this in {{location}} by showing real model photos and saying: \"Here is the simple way to get clothes, outfits, and styling help. send size and occasion on WhatsApp.\"","why_this_helps":"This works for a boutique because people decide faster when they can see proof, understand the offer, and know the next step without asking five extra questions.","how_to_check":"Compare the number before and after the action. Also check replies, saves, useful questions, and people who mention this boutique post."}', '["boutique","fashion","retail"]', '["running"]', '["women","students","young_professionals"]', '["instagram","whatsapp","google_business"]', '["standard_product"]', '["local_store","retail","custom_order"]', '["better_decisions","track_growth"]', '["no_budget","low_budget","medium_budget"]', '["local_city","india","kerala"]', '["no_tracking","unclear_results"]', 'easy', 'urgent', 'this_week', 5, 'beginner', 1, 'review-002-market-expansion', 'review-002-market-expansion', 'local-review');
